const geo = msg.metadata.geo;
const target = msg.metadata.target;
const source = msg.metadata.source;
const utils = global.get("utils");
const base_url = global.get("parat_bridge").base_urls.wasos;
const callsign = `${utils.build_callsign(source)} ${msg.entry.author}`;

const groupId = target.client_specific.room_id;
if (!groupId) {
    node.warn("No WaSOS room UUID available for geo operations");
    return null;
}

// Deterministic marker UUID from source + delhendelse name                                                                                                         
const hash = crypto.createHash('sha256')
    .update(`${source.identifier}_${geo.name}`)
    .digest('hex');
const marker_uuid = `${hash.slice(0, 8)}-${hash.slice(8, 12)}-${hash.slice(12, 16)}-${hash.slice(16, 20)}-${hash.slice(20, 32)}`;

const geoFeature = {
    type: "Feature",
    properties: {
        objecttype: "chat",
        description: geo.name,
        color: "blue",
        username: callsign,
        groups: [groupId],
        id: callsign
    },
    geometry: {
        type: "Point",
        coordinates: [geo.lng, geo.lat]
    }
};

msg._marker_data = {
    url: base_url + "/api/geo/markers/" + marker_uuid,
    headers: {
        "x-api-key": target.api_key,
        "Content-Type": "application/json"
    },
    payload: {
        classification: "U",
        collaborative: false,
        color: "red",
        description: `[${source.client_system} - ${source.name}] ${geo.name}`,
        files: [],
        geometry: {
            type: "Point",
            coordinates: [geo.lng, geo.lat]
        },
        groups: [groupId],
        objectType: "marker"
    }
};

msg.url = base_url + "/api/chat/messages/"
    + target.client_specific.chatroom_name;
msg.headers = {
    "x-api-key": target.api_key,
    "Content-Type": "application/json"
};
msg.payload = {
    content: JSON.stringify(geoFeature),
    callsign: callsign,
    isLocation: true,
    replyMessageId: null,
    files: []
};

return msg;

const markerData = msg._marker_data;
if (!markerData) {
    node.warn("No marker data available");
    return null;
}

msg.url = markerData.url;
msg.headers = markerData.headers;
msg.payload = markerData.payload;

return msg;

if (msg.statusCode && msg.statusCode >= 400) {
    node.warn(`Marker upsert failed (status ${msg.statusCode}): ${msg.payload}`);
}

delete msg._marker_data;
return msg;
